    synchronized void stateObject(String key,JSONObject value){if(value==null)state.remove(key);else put(state,key,copy(value));save();if(key.equals("token")&&this==NoirApp.data)NoirApp.scheduleSync(context);}
    static final String[] PAIRING={"address","pin","token","library","clockOffset","lastSync","lastSyncState","profileEdit"};
    // A phone backup never carries the PC pairing or sign-ins.
    synchronized JSONObject backupState(){JSONObject copy=copy(state);for(String k:PAIRING)copy.remove(k);copy.remove("nuvio");copy.remove("stremio");return copy;}
    synchronized void replaceState(JSONObject restored){JSONObject next=copy(restored);for(String k:PAIRING)if(state.has(k))put(next,k,state.opt(k));for(String k:new String[]{"nuvio","stremio"})if(state.has(k))put(next,k,state.opt(k));state=next;save();}
    // Forgets one viewing, or every viewing of the item when viewingId is empty (un-checking it).
